// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts@4.9.3/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts@4.9.3/access/Ownable.sol";
import "@openzeppelin/contracts@4.9.3/utils/Strings.sol";

contract StarForgeRelic is ERC1155, Ownable {
    using Strings for uint256;

    address public gameContract;

    uint256 private _nextRelicId;

    struct RelicData {
        RelicType relicType;
        uint8 value;
        string name;
    }

    enum RelicType {
        ATTACK_BOOST,
        DEFENSE_BOOST,
        SPEED_BOOST,
        HP_BOOST,
        CRIT_CHANCE,
        LAST_STAND
    }

    mapping(uint256 => RelicData) public relics;

    event RelicMinted(address indexed to, uint256 id, RelicType relicType, uint8 value, string name);

    modifier onlyGameContract() {
        require(msg.sender == gameContract, "Only StarForgeGame contract can mint relics");
        _;
    }

    constructor() ERC1155("") Ownable() {}

    function setGameContract(address _gameContract) external onlyOwner {
        gameContract = _gameContract;
    }

    function mintRelic(
        address to,
        RelicType relicType,
        uint8 value
    ) external onlyGameContract returns (uint256) {
        uint256 id = _nextRelicId++;
        string memory name = _generateRelicName(relicType, value);

        _mint(to, id, 1, "");

        relics[id] = RelicData({
            relicType: relicType,
            value: value,
            name: name
        });

        emit RelicMinted(to, id, relicType, value, name);
        return id;
    }

    function getRelic(uint256 id) external view returns (RelicData memory) {
        require(relics[id].value > 0, "Relic does not exist");
        return relics[id];
    }

    function _generateRelicName(RelicType t, uint8 value) internal pure returns (string memory) {
        if (t == RelicType.ATTACK_BOOST)    return string(abi.encodePacked("Quantum Strike +", Strings.toString(uint256(value))));
        if (t == RelicType.DEFENSE_BOOST)   return string(abi.encodePacked("Void Shield +", Strings.toString(uint256(value))));
        if (t == RelicType.SPEED_BOOST)     return string(abi.encodePacked("Nebula Dash +", Strings.toString(uint256(value))));
        if (t == RelicType.HP_BOOST)        return string(abi.encodePacked("Echo Core +", Strings.toString(uint256(value))));
        if (t == RelicType.CRIT_CHANCE)     return string(abi.encodePacked("Flux Overload +", Strings.toString(uint256(value))));
        return string(abi.encodePacked("Last Stand +", Strings.toString(uint256(value))));
    }

    function uri(uint256 id) public view override returns (string memory) {
        RelicData memory r = relics[id];
        if (r.value == 0) return "";
        return super.uri(id);
    }

    function totalSupply() external view returns (uint256) {
        return _nextRelicId;
    }

    // ==================== SOULBOUND: DISABLE TRANSFERS ====================

    function safeTransferFrom(address, address, uint256, uint256, bytes memory) public pure override {
        revert("Soulbound: transfers are disabled");
    }

    function safeBatchTransferFrom(address, address, uint256[] memory, uint256[] memory, bytes memory) public pure override {
        revert("Soulbound: transfers are disabled");
    }
}

StarForgeUnitNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts@4.9.3/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts@4.9.3/access/Ownable.sol";
import "@openzeppelin/contracts@4.9.3/utils/Strings.sol";
import "@openzeppelin/contracts@4.9.3/utils/Base64.sol";

contract StarForgeUnitNFT is ERC721, Ownable {
    using Strings for uint256;

    uint256 private _nextTokenId;

    enum Faction { Empire, Voidborn, Mechanoids }
    enum Rarity { Common, Rare, Legendary }
    enum UnitClass { Fighter, Cruiser, Dreadnought, DroneSwarm }

    struct Unit {
        Faction faction;
        Rarity rarity;
        UnitClass unitClass;
        uint8 attack;
        uint8 defense;
        uint8 speed;
    }

    mapping(uint256 => Unit) public units;

    address public gameContract;

    event UnitMinted(address to, uint256 tokenId, Faction faction, Rarity rarity, UnitClass unitClass);

    modifier onlyGameContract() {
        require(msg.sender == gameContract, "Only Game contract can mint");
        _;
    }

    constructor() ERC721("Somnia StarForge Unit", "SFUNIT") Ownable() {}

    function setGameContract(address _gameContract) external onlyOwner {
        gameContract = _gameContract;
    }

    function mintUnit(
        address to,
        Faction faction,
        Rarity rarity,
        UnitClass unitClass,
        uint8 atk,
        uint8 def,
        uint8 spd
    ) external onlyGameContract returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);

        units[tokenId] = Unit({
            faction: faction,
            rarity: rarity,
            unitClass: unitClass,
            attack: atk,
            defense: def,
            speed: spd
        });

        emit UnitMinted(to, tokenId, faction, rarity, unitClass);
        return tokenId;
    }

    function getUnit(uint256 tokenId) external view returns (Unit memory) {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        return units[tokenId];
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_ownerOf(tokenId) != address(0), "URI query for nonexistent token");
        Unit memory u = units[tokenId];

        string memory json = string(abi.encodePacked(
            '{"name":"StarForge Unit #', tokenId.toString(), '",',
            '"description":"On-chain unit from Somnia StarForge - Echo of Dreams",',
            '"image":"https://your-cdn.com/units/', 
                _getClassName(u.unitClass), '_', 
                _getFactionName(u.faction), '_', 
                _getRarityName(u.rarity), '.png",',
            '"attributes":[',
                '{"trait_type":"Faction","value":"', _getFactionName(u.faction), '"},',
                '{"trait_type":"Rarity","value":"', _getRarityName(u.rarity), '"},',
                '{"trait_type":"Class","value":"', _getClassName(u.unitClass), '"},',
                '{"trait_type":"Attack","value":', uint256(u.attack).toString(), '},',
                '{"trait_type":"Defense","value":', uint256(u.defense).toString(), '},',
                '{"trait_type":"Speed","value":', uint256(u.speed).toString(), '}',
            ']}'
        ));

        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(bytes(json))));
    }

    function _getFactionName(Faction f) internal pure returns (string memory) {
        if (f == Faction.Empire) return "Empire";
        if (f == Faction.Voidborn) return "Voidborn";
        return "Mechanoids";
    }

    function _getRarityName(Rarity r) internal pure returns (string memory) {
        if (r == Rarity.Common) return "Common";
        if (r == Rarity.Rare) return "Rare";
        return "Legendary";
    }

    function _getClassName(UnitClass c) internal pure returns (string memory) {
        if (c == UnitClass.Fighter) return "Fighter";
        if (c == UnitClass.Cruiser) return "Cruiser";
        if (c == UnitClass.Dreadnought) return "Dreadnought";
        return "DroneSwarm";
    }

    function totalSupply() external view returns (uint256) {
        return _nextTokenId;
    }

    function ownerMint(
        address to, 
        Faction faction, 
        Rarity rarity, 
        UnitClass unitClass, 
        uint8 atk, 
        uint8 def, 
        uint8 spd
    ) external onlyOwner {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        units[tokenId] = Unit(faction, rarity, unitClass, atk, def, spd);
    }

    // ==================== SOULBOUND: DISABLE TRANSFERS ====================

    function transferFrom(address, address, uint256) public pure override {
        revert("Soulbound: transfers are disabled");
    }

    function safeTransferFrom(address, address, uint256) public pure override {
        revert("Soulbound: transfers are disabled");
    }

    function safeTransferFrom(address, address, uint256, bytes memory) public pure override {
        revert("Soulbound: transfers are disabled");
    }

    function approve(address, uint256) public pure override {
        revert("Soulbound: approvals are disabled");
    }

    function setApprovalForAll(address, bool) public pure override {
        revert("Soulbound: approvals are disabled");
    }
}

